#!/usr/bin/env bash
# totalsegmri-pancreas: headline table via the shared aggregate_from_config.py (never hand-compute tables / p-values). Configs are GENERATED by 06_05_write_configs.sh.
#   bash 06_02_aggregate_from_config.sh configs/<config>.yaml
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${HERE}/../00_utils/env.sh"; cd "${PROJECT_ROOT}"
CFG="${1:?usage: $0 <config.yaml>}"; [[ "$CFG" != /* ]] && CFG="${HERE}/${CFG}"
.venv/bin/python benchmark/00_commun_scripts/00_03_evaluate/aggregate_from_config.py "${CFG}"
